class Solution:
    def countAlternatingSubarrays(self, nums: List[int]) -> int:
        ans = cur = 1
        for i in range(1, len(nums)):
            if nums[i] != nums[i-1]:
                cur += 1
            else:
                ans += cur * (cur + 1) // 2
                cur = 1
        return ans + cur * (cur + 1) // 2

