class Solution {
public:
    long long countAlternatingSubarrays(vector<int>& nums) {
        long long ans = 0, cur = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (i && nums[i] == nums[i-1]) { ans += cur * (cur + 1) / 2; cur = 0; }
            cur++;
        }
        return ans + cur * (cur + 1) / 2;
    }
};

